from docx.shared import Inches, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from PIL import Image, ImageDraw, ImageFont

ROOT=Path(__file__).parent
E=ROOT/'evidence'
DATA=json.loads((E/'figma.json').read_text(encoding='utf-8'))
FONT='C:/Windows/Fonts/malgun.ttf'
BASE='https://www.figma.com/design/EnCDeN7hohOA5p8rE2rsNA?node-id='
def url(n):return BASE+n.replace(':','-')
def link(p,label,target):
 h=OxmlElement('w:hyperlink');h.set(qn('r:id'),p.part.relate_to(target,'http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink',is_external=True));r=OxmlElement('w:r');pr=OxmlElement('w:rPr');c=OxmlElement('w:color');c.set(qn('w:val'),'245A81');pr.append(c);r.append(pr);t=OxmlElement('w:t');t.text=label;r.append(t);h.append(r);p._p.append(h)
def p(d,s,style=None):return d.add_paragraph(s,style)
def h(d,s):d.add_heading(s,1)
def page(d,s):
 q=d.add_heading(s,1);q.paragraph_format.page_break_before=True
def table(d,heads,rows,widths=None):
 t=d.add_table(rows=1,cols=len(heads));t.autofit=False
 widths=widths or [6.85/len(heads)]*len(heads)
 for col,w in zip(t.columns,widths):col.width=Inches(w)
 for i,x in enumerate(heads):t.rows[0].cells[i].text=x
 for row in rows:
  cells=t.add_row().cells
  for i,x in enumerate(row):cells[i].text=str(x)
 for ri,row in enumerate(t.rows):
  trpr=row._tr.get_or_add_trPr();v=OxmlElement('w:cantSplit');trpr.append(v)
  if ri==0:v=OxmlElement('w:tblHeader');trpr.append(v)
  for ci,c in enumerate(row.cells):
   c.width=Inches(widths[ci]);tc=c._tc.get_or_add_tcPr();sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'DFEAF2' if ri==0 else ('F6F8FA' if ri%2==0 else 'FFFFFF'));tc.append(sh)
   bd=OxmlElement('w:tcBorders')
   for edge in ['top','left','bottom','right']:
    el=OxmlElement('w:'+edge);el.set(qn('w:val'),'single');el.set(qn('w:sz'),'4');el.set(qn('w:color'),'D9D9D9');bd.append(el)
   tc.append(bd);mar=OxmlElement('w:tcMar')
   for edge in ['top','bottom','left','right']:
    el=OxmlElement('w:'+edge);el.set(qn('w:w'),'85');el.set(qn('w:type'),'dxa');mar.append(el)
   tc.append(mar)
   for par in c.paragraphs:
    par.paragraph_format.space_after=Pt(2);par.paragraph_format.space_before=Pt(2);par.paragraph_format.line_spacing=1.05
    for run in par.runs:run.font.size=Pt(9);run.bold=ri==0
 p(d,'').paragraph_format.space_after=Pt(0)
 return t
def shot(d,node,caption):
 f=E/(node.replace(':','-')+'.png')
 if f.exists():
  d.add_picture(str(f),width=Inches(6.4));d.paragraphs[-1].alignment=1
 q=p(d,caption,'Caption');link(q,'  Figma 화면',url(node))
def new(kind):
 d=Document();sec=d.sections[0];sec.page_width=Inches(8.27);sec.page_height=Inches(11.69);sec.top_margin=Inches(.68);sec.bottom_margin=Inches(.65);sec.left_margin=sec.right_margin=Inches(.71)
 for name in ['Normal','Title','Subtitle','Heading 1','Heading 2','Caption']:
  st=d.styles[name];st.font.name='Malgun Gothic';st._element.get_or_add_rPr().rFonts.set(qn('w:eastAsia'),'Malgun Gothic');st.font.color.rgb=RGBColor(0,0,0)
 for st in d.styles:
  for bd in list(st.element.iter(qn('w:pBdr'))):bd.getparent().remove(bd)
 sec.bottom_margin=Inches(.8)
 d.styles['Normal'].font.size=Pt(10);d.styles['Normal'].paragraph_format.space_after=Pt(5);d.styles['Normal'].paragraph_format.line_spacing=1.1
 d.styles['Title'].font.size=Pt(27);d.styles['Heading 1'].font.size=Pt(17);d.styles['Heading 2'].font.size=Pt(12);d.styles['Caption'].font.size=Pt(8)
 sec.header.paragraphs[0].text='VESTIGIA   /   '+kind+' UI 명세서   /   초안 v0.1'
 sec.header.paragraphs[0].style='Caption'
 ft=sec.footer.paragraphs[0];ft.alignment=2;ft.add_run('2026 09 25   ·   ');fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');ft._p.append(fld)
 d.core_properties.title='VESTIGIA '+kind+' UI 명세서 초안';d.core_properties.author='VESTIGIA 프로젝트'
 d.add_heading('VESTIGIA '+kind+' UI 명세서',0);p(d,'와이어프레임과 프로토타입 기반 구현 검토 초안','Subtitle')
 p(d,'버전 0.1  |  작성 기준일 2026년 9월 25일  |  대상 기획 아트 개발 QA')
 p(d,'이 문서는 현재 Figma의 화면 구조와 연결을 구현 가능한 UI 동작으로 정리한 초안이다. 화면 정의, 입력과 상태 전환, 데이터 표시, 화면 크기 대응, 예외 처리와 검증 기준을 함께 제공한다. 최종 승인 규격은 아니며 미확인 항목은 마지막 확인 목록에서 결정한다.')
 table(d,['표기','의미'],[['[관찰]','현재 Figma 화면·레이어·프로토타입 설정에서 확인한 내용'],['[기획]','로컬 현행 시스템 기획서에 명시된 요구사항'],['[제안]','구현을 위해 초안에서 보완한 UX 규격이며 승인 전'],['[미확인]','자료로 결정할 수 없거나 화면과 규칙 사이에 차이가 있는 항목']],[1.05,5.8])
 p(d,'검증 범위  전투와 가방 페이지의 폐기 프레임을 제외한 전체 화면 텍스트·하위 노드 연결을 조회했다. 대표 화면 렌더를 확인했다. Figma 플레이어에서 실제 터치·드래그를 재생하거나 게임의 데이터 저장·판정을 실행 검증한 것은 아니다. 연결은 정적 프레임 전환이며 게임 로직 구현을 뜻하지 않는다.')
 p(d,'자료 기준  system-spec/확정의 로컬 사본을 사용했다. 이번 작성에서는 원격 저장소와 최신성 동기화를 확인하지 않았다. 관리대장은 시스템을 확정으로 분류하지만 일부 문서 상단의 제안·임시 표기가 남아 있다. 개별 미정과 [임시] 전투 시뮬레이션 상태는 유지했다. 팀원 프로토타입과 과거 지시는 새로운 승인으로 취급하지 않았다.')
 return d

def flow(name,nodes,edges,height=1050):
 if name=='battle-flow':
  nodes={'a':(560,20,480,85,'전투 진입 · 선공과 슬롯 구성 [기획]'),'b':(560,165,480,90,'턴 설계 · 적 계획 확인'),'c':(30,320,460,110,'아군 선택 → 이동 → 주 행동 지정\n확정 / 철회 후 턴 설계 복귀'),'t':(1110,320,460,110,'현재 + 파편 100 이상 → 시간 전환\n갱신·계획 재검증 후 턴 설계 복귀'),'o':(30,560,460,110,'미래 관측 · 가상 실행 [임시]\n종료 / 취소 → 기존 계획 복귀'),'r':(560,560,480,110,'작전 개시\n편집 잠금 · 순서대로 실제 실행'),'e':(560,820,480,100,'턴 종료 → 다음 턴 설계\n승패 확정 → 결과 화면 [미확인]')}
  edges=[('a','b',''),('b','c',''),('b','t',''),('b','o',''),('b','r',''),('r','e','')]
 if name=='bag-flow':
  edges=[('a','b',''),('a','c',''),('c','e','드래그'),('d','f','획득 처리'),('e','g','검증'),('g','h',''),('g','i','')]
 im=Image.new('RGB',(1600,height),'white');dr=ImageDraw.Draw(im);font=ImageFont.truetype(FONT,25)
 for a,b,label in edges:
  x,y,w,hh,_=nodes[a];xx,yy,ww,h2,_=nodes[b];start=(x+w/2,y+hh);end=(xx+ww/2,yy)
  if yy<=y: start=(x+w,y+hh/2);end=(xx+ww,yy+h2/2);mid=max(x+w,xx+ww)+45;pts=[start,(mid,start[1]),(mid,end[1]),end]
  else:
   if name=='battle-flow' and b=='o':pts=[(560,210),(515,210),(515,500),(260,500),end]
   else:pts=[start,(start[0],(start[1]+end[1])/2),(end[0],(start[1]+end[1])/2),end]
  dr.line(pts,fill='#426478',width=4);dx=end[0]-pts[-2][0];dy=end[1]-pts[-2][1];ang=math.atan2(dy,dx);dr.polygon([end,(end[0]-15*math.cos(ang-.45),end[1]-15*math.sin(ang-.45)),(end[0]-15*math.cos(ang+.45),end[1]-15*math.sin(ang+.45))],fill='#426478')
  if label:dr.text((pts[1][0]+8,pts[1][1]-30),label,font=font,fill='#244050')
 for x,y,w,hh,label in nodes.values():
  dr.rounded_rectangle((x,y,x+w,y+hh),radius=12,fill='#EEF3F7',outline='#476575',width=3)
  bb=dr.multiline_textbbox((0,0),label,font=font,spacing=9,align='center');dr.multiline_text((x+(w-(bb[2]-bb[0]))/2,y+(hh-(bb[3]-bb[1]))/2-5),label,font=font,fill='#17232A',spacing=9,align='center')
 im.save(E/(name+'.png'))

def screen(d,title,node,scope,rows,notes):
 page(d,title);p(d,scope);shot(d,node,'[관찰] 대표 화면 '+node)
 table(d,['요소 또는 입력','표시와 동작 정의'],rows,[1.6,5.25])
 for s in notes:p(d,s)

def appendix(d,pi):
 page(d,'부록 화면과 프로토타입 연결 목록')
 p(d,'[관찰] 같은 이름의 화면은 node ID로 구별한다. 아래 목록은 모든 현재 프레임의 연결 요약이다. 숨김 레이어와 목적지 없는 액션은 제외했다. visible 속성이 켜져 있어도 프레임 밖에 놓인 요소는 실제 화면에서 누를 수 없을 수 있다. 자동 전환의 숫자는 지연 시간이며 게임 연출 확정값이 아니다.')
 details=DATA['details'][pi]
 for f in details:
  q=d.add_heading(f['name']+'  '+f['id'],2);link(q,'  원본',url(f['id']))
  lines=[]
  for l in f['links']:
   if not l['visible']:continue
   for r in l['reactions']:
    acts=r.get('actions') or ([r['action']] if r.get('action') else [])
    for a in acts:
     if not a.get('destinationId'):continue
     tr=r.get('trigger') or {};ty=tr.get('type','');ty={'ON_CLICK':'클릭','ON_DRAG':'드래그','AFTER_TIMEOUT':'자동'}.get(ty,ty)
     if 'timeout' in tr:ty+=' '+str(round(tr['timeout'],2))+'초'
     line=f"{l['name']} · {ty} → {a['destinationId']}"
     trans=a.get('transition')
     if trans:line+=' · '+trans['type']+' '+str(round(trans.get('duration',0),2))+'초'
     if line not in lines:lines.append(line)
  p(d,'\n'.join(lines) if lines else '조회된 표시 노드에서 목적지 연결 없음')

